-- Thread 1 (sort 357): the-temple-veil-rent-and-the-way-back-into-the-most-holy-place-opened-in-2-baruch-and-testaments-xii
INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'the-temple-veil-rent-and-the-way-back-into-the-most-holy-place-opened-in-2-baruch-and-testaments-xii',
       'The temple-veil rent and the way back into the Most-Holy-Place opened — 2 Baruch 6 and Testaments of the XII / Levi 3-4 (FRAMEWORK-MAJOR)',
       'Matt 27:51-52''s *and, behold, the veil of the temple was rent in twain from the top to the bottom; and the earth did quake, and the rocks rent; and the graves were opened* — read against the wisdom-stream''s direct external-witness articulation of the veil-and-the-Most-Holy-Place architecture in 2 Baruch 6 and Testaments of the XII Patriarchs / Levi 3-4. Four moves: 2 Baruch 6:7 (Charles seq #3, v.7) names the angel-descending-into-the-Holy-of-Holies-and-taking-the-veil substance (*I saw him descend into the Holy of Holies, and take from thence the veil, and the holy ark, and the mercy-seat*) — the wisdom-stream''s heavenly-register articulation of the action-upon-the-veil the Father walks-out at the cross from the heavenly-side, tearing-it from-the-top-to-the-bottom; Test. Levi 3:5 / 4:2 conjoint (Charles seq #14, v.5) names the gates-of-heaven-opened-and-the-holy-temple-seen-and-upon-a-throne-of-glory-the-Most-High substance — the gates-of-heaven the Test. Levi vision opened are the gates the Father walks-out at the cross in operative-form; Test. Levi 4:2 (Charles seq #15, v.2) names the *I have given thee the blessings of the priesthood until I come and sojourn in the midst of Yashar''el (Israel)* — the *I come and sojourn* the Test. Levi vision named is the incarnation-and-cross-substance walking-out per John 1:14''s *the Word was made flesh, and dwelt (skēnoō — tabernacled) among us*; Test. Levi 4:17 (Charles seq #15, v.17) names the *some of them shall be high priests, and judges, and scribes; for by their mouth shall the holy place be guarded* substance the saints-arising at Matt 27:52 walk-out at the historical-foretaste-substance per Red Line #11. The framework reads the cluster as FRAMEWORK-MAJOR. The *from the top to the bottom* direction names the Father-from-above tearing-the-veil-from-the-heavenly-side per Hebrews 10:19-22 — opening-the-way-back-into-the-Father''s-house, NOT the inherited-Christian-replacement-theology reading that the temple-system-is-now-replaced-by-the-church (the framework rejects the abolition-of-the-Father''s-house reading; the framework reads the veil-rent as Yahuah-opening-the-Way-back-into-the-Father''s-house per the *Grace, the Way, the New Heart, and the Mercy of Depart* exposition in framework-deep.md — grace as the means of return-to-the-Way, NOT the cancellation-of-the-curse-system).',
       sv.verse_id, ev.verse_id, 'complete_study', 357
  FROM _s156_xref_lookup sv, _s156_xref_lookup ev
 WHERE sv.edition_slug = 'canon' AND sv.book_slug = 'matthew' AND sv.chapter_number = 27 AND sv.verse_number = 51
   AND ev.edition_slug = 'canon' AND ev.book_slug = 'matthew' AND ev.chapter_number = 27 AND ev.verse_number = 52
ON CONFLICT (slug) DO NOTHING;

-- Thread 2 (sort 358): the-faithful-righteous-suffering-unto-death-and-the-atoning-blood-architecture-in-4-maccabees
INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'the-faithful-righteous-suffering-unto-death-and-the-atoning-blood-architecture-in-4-maccabees',
       'The faithful righteous suffering unto death and the atoning blood architecture — 4 Maccabees 6-17''s seven-sons-and-the-mother + Eleazar witness to the cross (FRAMEWORK-MAJOR)',
       'Matt 27:42-50''s crucifixion-and-death — the mockers'' *he saved others; himself he cannot save. If he be the King of Yashar''el (Israel), let him now come down from the cross* + the mockers'' *he trusted in Elohim (God); let him deliver him now... for he said, I am the Son of Elohim (God)* + the King''s-voluntary-yielding-up-of-the-ghost — read against the wisdom-stream''s direct external-witness articulation of the faithful-righteous-suffering-unto-death-and-the-atoning-blood architecture in 4 Maccabees 6-17. Four moves: 4 Macc 15:3 (Charles seq #11, v.3) names the *loved rather religion, which saveth unto eternal life according to Elohim (God)* substance — the seven-sons-and-the-mother choosing the eternal-life-architecture over the present-life-preservation the mockers at Matt 27:42 demand; the King COULD-save-himself per Matt 26:53 + John 10:17-18 (the categorically-capable-Son chooses the cross-substance); 4 Macc 7:18-19 (Charles seq #6, v.18) names the *unto Elohim (God) they die not, as our patriarchs, Abraham and Isaac and Jacob, died not, but that they live unto Elohim (God)* substance — the patriarchs-sleeping-awaiting-the-first-resurrection architecture per Red Line #11 (Romans 11:24''s natural-branches-able-to-be-grafted-in-again); 4 Macc 17:13 (Charles seq #13, v.13) names the *prize of victory in incorruption in everlasting life* substance — the endurance-unto-the-prize architecture the King walks-out at the supreme-substance of the voluntary-yielding-up-of-the-ghost at Matt 27:50; 4 Macc 17:18-22 (Charles seq #13, v.18) names THE direct verbal-anchor for the *ransom for our nation''s sin + the blood of these righteous men + the propitiation of their death + the divine Providence delivered Yashar''el (Israel)* substance — the wisdom-stream had named the categorically-exempt-righteous-paying-the-atonement-substance-the-categorically-bound-owed architecture at the seven-sons-and-the-mother martyrdom-witness centuries before the cross; the cross walks-it-out at universal-scale per Hebrews 7:27''s *this he did once, when he offered up himself.* Read CAREFULLY against the framework''s reading per the *Grace, the Way, the New Heart, and the Mercy of Depart* section of framework-deep.md — the cross is the door-home opening architecturally (grace as the means of return-to-the-Way), NOT the inherited-Reformation-forensic-substitutionary-juridical-transaction collapse that the cross cancels-the-curse-system; the framework reads the categorically-exempt-One-paying-the-atonement-substance-the-categorically-bound-owed in continuity with the Matt-17:24-27 temple-tax pre-figuring (S154''s thread `the-just-man-as-son-of-yahuah-condemned-and-vindicated-in-wisdom-of-solomon-2` names this architecture in miniature at the temple-tax-substance; Matt 27:50 walks-it-out at full-scale via the wisdom-stream''s 4 Maccabees witness). FRAMEWORK-MAJOR.',
       sv.verse_id, ev.verse_id, 'complete_study', 358
  FROM _s156_xref_lookup sv, _s156_xref_lookup ev
 WHERE sv.edition_slug = 'canon' AND sv.book_slug = 'matthew' AND sv.chapter_number = 27 AND sv.verse_number = 42
   AND ev.edition_slug = 'canon' AND ev.book_slug = 'matthew' AND ev.chapter_number = 27 AND ev.verse_number = 50
ON CONFLICT (slug) DO NOTHING;

-- Thread 3 (sort 359): the-kings-and-the-mighty-condemning-the-elect-one-and-the-elect-one-vindicated-on-the-throne-of-his-glory-in-1-enoch-parables
INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'the-kings-and-the-mighty-condemning-the-elect-one-and-the-elect-one-vindicated-on-the-throne-of-his-glory-in-1-enoch-parables',
       'The kings and the mighty condemning the Elect-One and the Elect-One vindicated on the throne of his glory — 1 Enoch 62-63''s Parables witness to the cross-and-the-day-of-vindication architecture',
       'Matt 27:1''s *all the chief priests and elders of the people took counsel against Yahusha (Jesus) to put him to death* + Matt 27:42-43''s mockers'' *if he be the King of Yashar''el (Israel), let him now come down from the cross* and *he trusted in Elohim (God); let him deliver him now* — read against the wisdom-stream''s direct articulation of the kings-and-the-mighty-condemning-the-Elect-One AND the eschatological-reversal of the Elect-One-on-the-throne-of-his-glory architecture in 1 Enoch 62-63''s Parables-of-Enoch. Four moves: 1 Enoch 63:1 names THE verbal-anchor for the kings-and-the-mighty-and-the-exalted-summoned-before-the-Elect-One substance — the present-tense-counsel-against-the-King at Matt 27:1 is the architectural-inverse of the day-of-vindication-summons the wisdom-stream named (the corrupted-Sanhedrin-leadership + Pontius-Pilate + Hordos (Herod)-Antipas take-counsel-against-the-Anointed per Tehillim (Psalm) 2:2 + Acts 4:25-28); 1 Enoch 62:3 names the Elect-One-summoned-with-the-host-of-the-heavens substance — the King COULD-have-summoned-twelve-legions-of-angels per Matt 26:53; he walks-the-cross-substantively per the Father''s-purpose; 1 Enoch 62:7 names THE direct verbal-anchor for the *righteousness of the Head of Days forsakes him not* substance — the wisdom-stream had named the Son-of-Adam''s-being-not-forsaken centuries before the cross; the King''s-prayer at Matt 27:46 (*Eli, Eli, lama sabachthani*) is the Suffering-Servant-praying-Tehillim 22 (which walks AS A WHOLE from apparent-forsakenness in vv.1-21 INTO vindication in vv.22-31), NOT the Trinity-co-equal-person-being-forsaken reading the inherited-Christian-collapse walks per Red Line #10''s nature-of-God reading; 1 Enoch 63:3 names the eschatological-reversal — the kings-and-the-mighty who-presently-mock at the cross shall-eventually fall-down-on-their-faces and worship the Son-of-Adam per Philippians 2:10-11''s *every knee should bow.* Threaded continuity with S155 Matt 22''s `the-elect-one-at-the-right-hand-the-davidic-lord-witnessed-in-1-enoch-parables` (different application — that thread anchors the Davidic-Lord-at-the-right-hand-Tehillim-110 enthronement; this thread anchors the suffering-that-precedes-the-vindication architecture the cross walks-out). The wisdom-stream and the gospel cohere at the Elect-One / Son-of-Adam architecture per Red Line #12''s reading: the canon-and-the-Parables-of-Enoch witness the same Formed-Son.',
       sv.verse_id, ev.verse_id, 'complete_study', 359
  FROM _s156_xref_lookup sv, _s156_xref_lookup ev
 WHERE sv.edition_slug = 'canon' AND sv.book_slug = 'matthew' AND sv.chapter_number = 27 AND sv.verse_number = 1
   AND ev.edition_slug = 'canon' AND ev.book_slug = 'matthew' AND ev.chapter_number = 27 AND ev.verse_number = 43
ON CONFLICT (slug) DO NOTHING;

-- Thread 4 (sort 360): the-day-of-the-most-high-cosmic-darkness-and-the-resurrection-of-the-righteous-in-2-esdras-and-2-baruch
INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'the-day-of-the-most-high-cosmic-darkness-and-the-resurrection-of-the-righteous-in-2-esdras-and-2-baruch',
       'The day of the Most-High, cosmic darkness, and the resurrection of the righteous — 2 Esdras 7 and 2 Baruch 51 witness to the cross-and-the-saints-arising architecture',
       'Matt 27:45-53''s *from the sixth hour there was darkness over all the land unto the ninth hour* + the temple-veil-rent + the earthquake + the rocks-rent + *the graves were opened; and many bodies of the saints which slept arose, and came out of the graves after his resurrection* — read against the wisdom-stream''s direct articulation of the cosmic-darkness-at-the-Messiah''s-death AND the resurrection-of-the-righteous architecture in 2 Esdras (4 Ezra) 7 and 2 Baruch 51. Four moves: 2 Esdras 7:30 names THE direct verbal-anchor for the *world shall be turned into the old silence seven days, like as in the former judgments* substance — the apocalyptic-stream had named the architecture of the cosmic-darkness-and-silence at the Messiah''s-death centuries before the cross (2 Esdras 7:28-29 names directly: *my son the Messiah shall be revealed... after these years shall my son Messiah (Christ) die, and all men that have life. And the world shall be turned into the old silence seven days*); the three-hours-of-darkness at Matt 27:45 is the historical-pivot-foretaste of the broader-cosmic-darkness per Amos 8:9''s *I will cause the sun to go down at noon*; 2 Esdras 7:33 names the *Most High shall appear upon the seat of judgment* substance — the cosmic-signs at the cross are the historical-pivot-foretaste of the broader-day-of-the-Most-High per Haggai 2:6-7 + Hebrews 12:26-27; 2 Esdras 7:32 names THE direct verbal-anchor for the *earth shall restore those that are asleep in her* substance — the saints-arising at Matt 27:52 is the historical-pivot-foretaste of the broader-first-resurrection per Red Line #11; 2 Baruch 51:1 names the *saved by their works... shall behold the world which is now invisible to them* substance — the resurrection-glory architecture the saints-arising-and-appearing-in-the-holy-city at Matt 27:53 walks-out at the historical-pivot-foretaste. The framework reads the cluster carefully per Red Line #11''s first-resurrection-foretaste reading: the forefathers-who-walked-the-covenant-faithfully Yahuah is able to graft-in-again at the first-resurrection (Romans 11:24 + Hebrews 11:39-40); the Matt 27:52-53 saints-arising substance is the historical-foretaste-of-the-fuller-first-resurrection-at-the-King''s-coming. The framework reads the 2 Baruch 51:1 *saved by their works* substance CAREFULLY — NOT the inherited-Reformation-merit-doctrine collapse; the framework reads works as the fruit-of-the-Spirit-internalized-Torah per Yechezk''el (Ezekiel) 36:26-27 + Yirmeyahu (Jeremiah) 31:31-34''s new-covenant + James 2:14-26''s *faith without works is dead.* The wisdom-stream had named the architecture; the cross walks-out the historical-pivot-foretaste.',
       sv.verse_id, ev.verse_id, 'complete_study', 360
  FROM _s156_xref_lookup sv, _s156_xref_lookup ev
 WHERE sv.edition_slug = 'canon' AND sv.book_slug = 'matthew' AND sv.chapter_number = 27 AND sv.verse_number = 45
   AND ev.edition_slug = 'canon' AND ev.book_slug = 'matthew' AND ev.chapter_number = 27 AND ev.verse_number = 53
ON CONFLICT (slug) DO NOTHING;

-- Thread 5 (sort 361): the-beloved-crucified-on-a-tree-descended-and-risen-and-many-of-the-righteous-ascending-with-him-in-ascension-of-isaiah
INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'the-beloved-crucified-on-a-tree-descended-and-risen-and-many-of-the-righteous-ascending-with-him-in-ascension-of-isaiah',
       'The Beloved crucified on a tree, descended, risen, and many of the righteous ascending with Him — Ascension of Isaiah 9 and 11''s external witness to the cross-and-the-saints-arising (FRAMEWORK-MAJOR)',
       'Matt 27:32-60''s crucifixion-and-death-and-burial — Shim''on (Simon) of Cyrene bearing the cross + Gulgolta (Golgotha) + *they crucified him* + the temple-veil-rent + the earthquake + the saints-arising + the burial in Yoseph (Joseph) of Arimathea''s rich-man''s-tomb — read against the direct external-witness articulation in Ascension of Isaiah 9 and 11. Five moves: AI 9:14 names THE direct verbal-anchor for the *the god of that world will stretch forth his hand against the Son, and they will crucify Him on a tree, and will slay Him not knowing who He is* substance — the wisdom-stream''s articulation of the world-rulers-not-knowing-who-the-Son-is at the crucify-Him-on-a-tree substance per Devarim (Deuteronomy) 21:22-23 + Galatians 3:13 + 1 Corinthians 2:8''s *had they known it, they would not have crucified the Lord of glory*; AI 9:16 names the *plundered the angel of death, He will ascend on the third day* substance — the descent-to-plunder-the-angel-of-death architecture per Hosheia (Hosea) 6:2 + 13:14 + 1 Peter 3:18-20 + Hebrews 2:14-15; AI 9:17 names THE direct verbal-anchor for the *many of the righteous will ascend with Him, whose spirits do not receive their garments till Yahuah (Lord) Messiah (Christ) ascend and they ascend with Him* substance — the wisdom-stream''s articulation of the architecture Matt 27:52-53 walks-out at the historical-pivot (this IS the operative external-witness verbal-anchor for *the graves were opened; and many bodies of the saints which slept arose, and came out of the graves after his resurrection, and went into the holy city, and appeared unto many*); AI 11:20 names the *In Jerusalem indeed I saw Him being crucified on a tree* substance — the prophet-Yeshayahu (Isaiah) saw-in-vision what the King walked at the historical-pivot per John 12:41; AI 11:19 names the *delivered Him to the king, and crucified Him, and He descended to the angel of Sheol* substance — the burial + descent-into-the-place-of-the-dead architecture the rich-man''s-tomb-at-Matt-27:60 walks-out per Yeshayahu (Isaiah) 53:9''s *he made his grave with the wicked, and with the rich in his death.* Per Yoshi''s S32 sourcing-decision (api/seed.py:EDITION_PROFILES["ascension-isaiah"]), AI is the *first witness* aligning with the framework''s Formless-Father / Formed-of-the-Formless nature-of-God teaching — pre-Nicene, late-1st / early-2nd CE, before the Constantine-era Trinity-construct hardened. The framework reads the *roused the children of Yashar''el (Israel) against Him* substance at AI 11:19 CAREFULLY against Red Line #9 — the framework rejects the inherited-Christian-replacement-theology weaponization against the Yahudim (Jews) as a people; the adversary-roused-the-leadership-of-the-second-Temple-aristocracy at the historical-pivot, NOT the substantial-Yahudah (Jewish)-people-as-a-whole; the framework''s system-not-people posture per the four-costumes-and-their-victims architecture holds. The wisdom-stream and the gospel cohere at the substance the Father''s-purpose-walks-out at the cross + the resurrection + the saints-arising. FRAMEWORK-MAJOR.',
       sv.verse_id, ev.verse_id, 'complete_study', 361
  FROM _s156_xref_lookup sv, _s156_xref_lookup ev
 WHERE sv.edition_slug = 'canon' AND sv.book_slug = 'matthew' AND sv.chapter_number = 27 AND sv.verse_number = 32
   AND ev.edition_slug = 'canon' AND ev.book_slug = 'matthew' AND ev.chapter_number = 27 AND ev.verse_number = 60
ON CONFLICT (slug) DO NOTHING;

