-- ---------------------------------------------------------------------
-- Verification block.
-- ---------------------------------------------------------------------
DO $verify$
DECLARE
  v_xref_inserted INT;
  v_thread_inserted INT;
  v_member_inserted INT;
BEGIN
  SELECT count(*) INTO v_xref_inserted FROM cross_references x
    JOIN _s156_xref_lookup sv ON sv.verse_id = x.source_verse_id
   WHERE sv.edition_slug = 'canon' AND sv.book_slug = 'matthew' AND sv.chapter_number = 27
     AND x.tier_required = 'extras' AND x.source = 'manual';

  SELECT count(*) INTO v_thread_inserted FROM cross_reference_threads
   WHERE slug IN (
     'the-temple-veil-rent-and-the-way-back-into-the-most-holy-place-opened-in-2-baruch-and-testaments-xii',
     'the-faithful-righteous-suffering-unto-death-and-the-atoning-blood-architecture-in-4-maccabees',
     'the-kings-and-the-mighty-condemning-the-elect-one-and-the-elect-one-vindicated-on-the-throne-of-his-glory-in-1-enoch-parables',
     'the-day-of-the-most-high-cosmic-darkness-and-the-resurrection-of-the-righteous-in-2-esdras-and-2-baruch',
     'the-beloved-crucified-on-a-tree-descended-and-risen-and-many-of-the-righteous-ascending-with-him-in-ascension-of-isaiah'
   );

  SELECT count(*) INTO v_member_inserted
    FROM cross_reference_thread_members m
    JOIN cross_reference_threads t ON t.id = m.thread_id
   WHERE t.slug IN (
     'the-temple-veil-rent-and-the-way-back-into-the-most-holy-place-opened-in-2-baruch-and-testaments-xii',
     'the-faithful-righteous-suffering-unto-death-and-the-atoning-blood-architecture-in-4-maccabees',
     'the-kings-and-the-mighty-condemning-the-elect-one-and-the-elect-one-vindicated-on-the-throne-of-his-glory-in-1-enoch-parables',
     'the-day-of-the-most-high-cosmic-darkness-and-the-resurrection-of-the-righteous-in-2-esdras-and-2-baruch',
     'the-beloved-crucified-on-a-tree-descended-and-risen-and-many-of-the-righteous-ascending-with-him-in-ascension-of-isaiah'
   );

  RAISE NOTICE 'S156 Matt 27 verify: extras xrefs from canon/matthew/27 = %, threads = %, members = %',
    v_xref_inserted, v_thread_inserted, v_member_inserted;

  IF v_thread_inserted <> 5 THEN
    RAISE EXCEPTION 'Expected 5 threads inserted; got %', v_thread_inserted;
  END IF;
  IF v_xref_inserted < 21 THEN
    RAISE EXCEPTION 'Expected at least 21 Matt-27 extras xrefs; got %', v_xref_inserted;
  END IF;
  IF v_member_inserted < 21 THEN
    RAISE EXCEPTION 'Expected at least 21 thread members; got %', v_member_inserted;
  END IF;
END;
$verify$;

COMMIT;
